const a = 2.0, c = 3.0;      // f(x) = a*(x-c)^2, minimum at x = c
console.log("f(x) = 2(x-3)^2, start x=0, 10 steps");
for (const lr of [0.01, 0.2, 0.6]) {
  let x = 0.0;
  for (let step = 0; step < 10; step++) {
    const grad = 2 * a * (x - c);   // df/dx
    x -= lr * grad;                 // error is multiplied by (1 - 2*a*lr)
  }
  const factor = 1 - 2 * a * lr;
  console.log(`lr=${lr.toFixed(2)} factor=${factor.toFixed(2)} x=${x.toFixed(4)}`);
}
// converges only when |factor| < 1, i.e. lr < 1/a = 0.5

