const t = 0;                         // target class

function loss(z) {
  const m = Math.max(...z);          // log-sum-exp trick for stability
  const lse = m + Math.log(z.reduce((s, v) => s + Math.exp(v - m), 0));
  return lse - z[t];                 // L = -z_t + ln(sum e^z_j)
}

const m = Math.max(...z);
const e = z.map(v => Math.exp(v - m));
const total = e.reduce((s, v) => s + v, 0);
const p = e.map(v => v / total);     // softmax probabilities
const grad = p.map((v, i) => v - (i === t ? 1.0 : 0.0));   // p - one_hot
console.log("p = " + p.map(v => v.toFixed(4)).join(" "));
const eps = 1e-5;
for (let i = 0; i < 3; i++) {
  const zp = z.slice(); zp[i] += eps;
  const zm = z.slice(); zm[i] -= eps;
  const num = (loss(zp) - loss(zm)) / (2 * eps);   // central difference
  console.log(`i=${i} analytic=${grad[i].toFixed(4)} numeric=${num.toFixed(4)}`);
}
