import java.util.Locale;

public class Main {
    static double[] z = {2.0, 1.0, 0.1};   // logits
    static int t = 0;                      // target class

    static double loss(double[] z) {
        double m = Math.max(z[0], Math.max(z[1], z[2]));   // log-sum-exp trick
        double s = 0;
        for (double v : z) s += Math.exp(v - m);
        return m + Math.log(s) - z[t];     // L = -z_t + ln(sum e^z_j)
    }

    public static void main(String[] args) {
        double m = Math.max(z[0], Math.max(z[1], z[2]));
        double[] e = new double[3];
        double total = 0;
        for (int i = 0; i < 3; i++) { e[i] = Math.exp(z[i] - m); total += e[i]; }
        double[] grad = new double[3];
        StringBuilder sb = new StringBuilder("p =");
        double gsum = 0;
        for (int i = 0; i < 3; i++) {
            double p = e[i] / total;                       // softmax probability
            grad[i] = p - (i == t ? 1.0 : 0.0);            // p - one_hot
            gsum += grad[i];
            sb.append(String.format(Locale.US, " %.4f", p));
        }
        System.out.println(sb);
        double eps = 1e-5;
        for (int i = 0; i < 3; i++) {
            double[] zp = z.clone(); zp[i] += eps;
            double[] zm = z.clone(); zm[i] -= eps;
            double num = (loss(zp) - loss(zm)) / (2 * eps);   // central difference
            System.out.println(String.format(Locale.US, "i=%d analytic=%.4f numeric=%.4f", i, grad[i], num));
        }
        System.out.println(String.format(Locale.US, "sum of gradient = %.4f", Math.abs(gsum)));
    }
}

