function f(w) {                      // loss: w0^2 * w1 + sin(w1)
  return w[0] ** 2 * w[1] + Math.sin(w[1]);
}
const good = w => [2 * w[0] * w[1], w[0] ** 2 + Math.cos(w[1])];   // correct gradient
const buggy = w => [w[0] * w[1], w[0] ** 2 + Math.cos(w[1])];      // forgot the factor 2

function numeric(w, k, eps = 1e-5) {
  const wp = w.slice(); wp[k] += eps;
  const wm = w.slice(); wm[k] -= eps;
  return (f(wp) - f(wm)) / (2 * eps);        // central difference
}

const w = [1.5, 0.5];
console.log("w = [" + w.join(", ") + "]");
for (const [name, fn] of [["good", good], ["buggy", buggy]]) {
  const g = fn(w);
  for (let k = 0; k < 2; k++) {
    const n = numeric(w, k);
    const rel = Math.abs(g[k] - n) / (Math.abs(g[k]) + Math.abs(n));   // relative error
    const status = rel < 1e-6 ? "ok" : "BUG";
    console.log(`${name} param ${k}: analytic=${g[k].toFixed(5)} numeric=${n.toFixed(5)} rel=${rel.toFixed(4)} ${status}`);
  }
}

