import java.util.Locale;

public class Main {
    static double f(double[] w) {            // loss: w0^2 * w1 + sin(w1)
        return w[0] * w[0] * w[1] + Math.sin(w[1]);
    }

    static double[] grad(double[] w, boolean bug) {
        double g0 = bug ? w[0] * w[1] : 2 * w[0] * w[1];   // bug: forgot the factor 2
        return new double[]{g0, w[0] * w[0] + Math.cos(w[1])};
    }

    static double numeric(double[] w, int k) {
        double eps = 1e-5;
        double[] wp = w.clone(); wp[k] += eps;
        double[] wm = w.clone(); wm[k] -= eps;
        return (f(wp) - f(wm)) / (2 * eps);  // central difference
    }

    public static void main(String[] args) {
        double[] w = {1.5, 0.5};
        System.out.println("w = [1.5, 0.5]");
        String[] names = {"good", "buggy"};
        for (int c = 0; c < 2; c++) {
            double[] g = grad(w, c == 1);
            for (int k = 0; k < 2; k++) {
                double n = numeric(w, k);
                double rel = Math.abs(g[k] - n) / (Math.abs(g[k]) + Math.abs(n));   // relative error
                String status = rel < 1e-6 ? "ok" : "BUG";
                System.out.println(String.format(Locale.US, "%s param %d: analytic=%.5f numeric=%.5f rel=%.4f %s",
                    names[c], k, g[k], n, rel, status));
            }
        }
    }
}

