using System;
using System.Globalization;

class Program
{
    static double F(double[] w)              // loss: w0^2 * w1 + sin(w1)
    {
        return w[0] * w[0] * w[1] + Math.Sin(w[1]);
    }

    static double[] Grad(double[] w, bool bug)
    {
        double g0 = bug ? w[0] * w[1] : 2 * w[0] * w[1];   // bug: forgot the factor 2
        return new double[] { g0, w[0] * w[0] + Math.Cos(w[1]) };
    }

    static double Numeric(double[] w, int k)
    {
        double eps = 1e-5;
        double[] wp = (double[])w.Clone(); wp[k] += eps;
        double[] wm = (double[])w.Clone(); wm[k] -= eps;
        return (F(wp) - F(wm)) / (2 * eps);  // central difference
    }

    static void Main()
    {
        CultureInfo ci = CultureInfo.InvariantCulture;
        double[] w = { 1.5, 0.5 };
        Console.WriteLine("w = [1.5, 0.5]");
        string[] names = { "good", "buggy" };
        for (int c = 0; c < 2; c++)
        {
            double[] g = Grad(w, c == 1);
            for (int k = 0; k < 2; k++)
            {
                double n = Numeric(w, k);
                double rel = Math.Abs(g[k] - n) / (Math.Abs(g[k]) + Math.Abs(n));   // relative error
                string status = rel < 1e-6 ? "ok" : "BUG";
                Console.WriteLine(names[c] + " param " + k + ": analytic=" + g[k].ToString("F5", ci)
                    + " numeric=" + n.ToString("F5", ci) + " rel=" + rel.ToString("F4", ci) + " " + status);
            }
        }
    }
}
